INSERT INTO T_FAD_RISK_ANNEX VALUES(v,'BO37','RM48','Instances of non-compliance with MORA and SBP instructions on Hajj Schemes were noted, including incomplete application formalities, delayed data entry on the MORA website, missing or incomplete documents (passports, medical certificates, photos, vaccination certificates, affidavits), missed deadlines, and failure to collect applicable dues as per guidelines.','MEDIUM','Annexure!C73:G73');
INSERT INTO T_FAD_RISK_ANNEX VALUES(v,'BO38','RM48','Instances where the bank''s instructions related to Home Remittance transactions were not followed, particularly in areas such as conducting due diligence of customers and obtaining the minimum required documents (e.g., copy of CNIC, name screening, biometric verification), adherence to the turnaround time (TAT) for processing transactions, ID management, and the handling of customer queries and complaints.','MEDIUM','Annexure!C74:G74');
INSERT INTO T_FAD_RISK_ANNEX VALUES(v,'BO35','RM49','Instances of non-adherence to bank instructions were observed in Term Deposit Receipt (TDR) operations, including issuance, encashment (pre/post-maturity), rollover, profit payment, and WHT deduction/exemption. Similar lapses were noted in the issuance, payment, and cancellation of Bankers Cheques/CDRs, indicating non-compliance with relevant SOPs. ','MEDIUM','Annexure!C75:G75');
